-- Four CityFALCON read operations, checked against actual 2026-09-13 provider responses.

BEGIN;

SELECT pg_advisory_xact_lock(hashtext('cityfalcon-v2-contracts'));

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM providers.apis WHERE id='047f5d78-2357-493c-86e1-f6b558684edf' AND slug='cityfalcon-financial-api' AND origin_url='https://api.cityfalcon.com/v0.2' AND status='active' AND suspended_at IS NULL) THEN RAISE EXCEPTION 'CityFALCON identity changed'; END IF; END $guard$;

