INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('finance_markets.cityfalcon-news','Financial news','CityFALCON financial news for explicit full tickers (AAPL_US). Recent 30-day provider window only; this is the returned page, not an exhaustive historical record.  Use optional period/date fields when requested.','finance','{"type":"object","title":"Retrieve news and content text, metadata, and analytics","$schema":"http://json-schema.org/draft-07/schema#","properties":{"events":{"type":"string","description":"Comma-separated EVENT slugs -- defined occurrences such as a stock buyback or an analyst sell rating. Not topic classes (\"people\", \"commodities\" and the like belong in topic_classes) and not macro topics. Browse the slugs: https://www.cityfalcon.ai/help/articles/36799477030301","requiredOneOf":"selector"},"languages":{"type":"string","example":"en","description":"Comma-separated language codes (e.g. en, de, fr). Leave blank to get content in all languages."},"categories":{"type":"string","example":"mp,op","description":"Comma-separated category slugs: mp (major news publications), op (other news publications), r (research publications)."},"identifiers":{"type":"string","example":"AAPL_US,BTC_GLOBAL","description":"Comma-separated, and read according to identifier_type. With full_tickers: [ticker]_[country], e.g. AAPL_US, 005930_KR; cryptocurrencies use GLOBAL, e.g. BTC_GLOBAL. With assets: the NAME of a commodity (Aluminium, Brent Crude Oil, Gold, Wheat) or of a macro topic (Inflation, Core CPI, Unemployment Rates, Yield Curve). Leave this empty when you use topic_classes.","requiredOneOf":"selector"},"time_filter":{"enum":["m5","m15","h1","h8","d1","w1","mth1"],"type":"string","default":"d1","description":"Time window: m5 (5 min), m15 (15 min), h1 (1 hour), h8 (8 hours), d1 (1 day), w1 (1 week), mth1 (1 month). Queries cover the most recent 30 days only."},"dcsc_sectors":{"type":"string","description":"Comma-separated DCSC SECTOR slugs only. Not commodities and not macro topics -- those go in identifiers with identifier_type = assets. Cannot be combined with the asset, ticker or full_ticker identifiers.","requiredOneOf":"selector"},"country_codes":{"type":"string","example":"US,GB","description":"Comma-separated country codes. Not attached to a company''s listing country but to the news."},"topic_classes":{"enum":["alternative-dats","bonds","closed-end-funds","commodities","corporate-bonds","cryptocurrencies","events","financial-topics","foreign-exchange","fundamental-analysis","funds","indices","macro-topics","mutual-funds","organisations","other-equity-securities","other-events","people","preferred-stocks","private-companies","products","property","ratings-research-firms","regulations","state-owned-companies","stocks","technical-analysis"],"type":"string","description":"Aggregate feed by topic or asset class. Pick from the list: these are the only accepted values. Use this INSTEAD OF identifiers and identifier_type, never alongside them. \"bonds\" means government and sovereign bonds; use \"corporate-bonds\" for corporates. \"events\" is the Major Business and Related Activities class. A macro topic such as Core CPI or Inflation does NOT belong here -- put it in identifiers with identifier_type = assets.","requiredOneOf":"selector"},"with_sentiment":{"type":"boolean","description":"Return the sentiment score for each story."},"identifier_type":{"enum":["tickers","full_tickers","assets"],"type":"string","default":"full_tickers","description":"How identifiers is read. full_tickers for listed companies and crypto ([ticker]_[country]). assets for commodity names and macro topics. tickers for a bare symbol without a country. Must match what you put in identifiers."},"dcsc_sector_level":{"type":"string","description":"Select a DCSC sector level to refine the search."},"min_cityfalcon_score":{"type":"number","format":"float","default":0,"example":50,"maximum":100,"minimum":0,"description":"Minimum CityFALCON relevance score, from 0 to 100."},"registration_required":{"type":"boolean","description":"Include / exclude publishers that require user registration."},"with_sentiments_by_entities":{"type":"boolean","description":"Return the sentiment score for each NLU entity (e.g. company) in each story."}},"description":"Query parameters for GET https://api.cityfalcon.com/v0.2/stories. Auth: access_token."}'::jsonb,'{"type":"object","required":["stories"],"properties":{"stories":{"type":"array","items":{"type":"object","required":["uuid","title","url","publishTime"],"properties":{"uuid":{"type":"string"},"title":{"type":"string"},"url":{"type":"string"},"publishTime":{"type":"string"}}}}}}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('finance_markets.cityfalcon-sentiment','Market sentiment','CityFALCON market sentiment for explicit full tickers (AAPL_US). Recent 30-day provider window only; this is the returned page, not an exhaustive historical record.  Use optional period/date fields when requested.','finance','{"type":"object","title":"Sentiment for entities","$schema":"http://json-schema.org/draft-07/schema#","required":["identifiers"],"properties":{"period":{"enum":["m5","m15","h1","h8","d1","w1","mth1"],"type":"string","default":"d1","description":"Time period over which sentiment is calculated: m5 (5 min), m15 (15 min), h1 (1 hour), h8 (8 hours), d1 (1 day), w1 (1 week), mth1 (1 month)."},"identifiers":{"type":"string","example":"AAPL_US,BTC_GLOBAL","description":"Comma-separated values, interpreted per `identifier_type`. Full tickers are built as [ticker]_[trading_country]: the ticker, an underscore, then the country code of listing — e.g. AAPL_US, 005930_KR. For disambiguation  of companies that share a ticker (e.g., AA_US and AA_GB for American Airlines and British American Tobacco). Cryptocurrencies are not country-bound and use GLOBAL, e.g. BTC_GLOBAL."},"identifier_type":{"enum":["full_tickers","countries","dcsc_sector_level1","dcsc_sector_level2","dcsc_sector_level3","dcsc_sector_level4"],"type":"string","default":"full_tickers","description":"Identifier type. Accepted values: full_tickers, countries, dcsc_sectors."},"average_for_period":{"type":"boolean","description":"Include average value for the period."},"statistics_for_period":{"type":"boolean","description":"Include statistics for the period."}},"description":"Query parameters for GET https://api.cityfalcon.com/v0.2/services/sentiment. Auth: access_token."}'::jsonb,'{"type":"object","required":["entities"],"properties":{"entities":{"type":"array","items":{"type":"object","required":["name","chartData"],"properties":{"name":{"type":"string"},"chartData":{"type":"object","required":["labels","values","confidence"],"properties":{"labels":{"type":"array","items":{"type":"string"}},"values":{"type":"array","items":{"type":"number"}},"confidence":{"type":"array","items":{"type":"number"}}}}}}}}}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('finance_markets.cityfalcon-insider-transactions','US insider transactions','CityFALCON us insider transactions for explicit full tickers (AAPL_US). Recent 30-day provider window only; this is the returned page, not an exhaustive historical record. US companies only. Use optional period/date fields when requested.','finance','{"type":"object","title":"Retrieves insider transactions for US companies","$schema":"http://json-schema.org/draft-07/schema#","required":["identifiers"],"properties":{"end_date":{"type":"integer","example":1632393143,"description":"Retrieve data to/before this date, as a UNIX timestamp, e.g. 1632393143."},"info_type":{"enum":["all","informative","uninformative"],"type":"string","default":"all","description":"Filter transactions by informative or uninformative."},"start_date":{"type":"integer","example":1632393143,"description":"Retrieve data from/after this date, as a UNIX timestamp, e.g. 1632393143. Limited to the most recent 30 days; older data is available as CSV from CityFALCON."},"identifiers":{"type":"string","example":"AAPL_US","description":"Comma-separated identifiers, format [ticker]_[trading_country], e.g. \"AAPL_US, 005930_KR\"."},"transaction_type":{"type":"string","example":"buy,sell","description":"Comma-separated transaction types, e.g. \"buy, sell, gift, option exercised, other\"."}},"description":"Query parameters for GET https://api.cityfalcon.com/v0.2/insider_transactions. Auth: access_token."}'::jsonb,'{"type":"array","items":{"type":"object","required":["ticker","transactionDate","transactionType","sourceURL"],"properties":{"ticker":{"type":"string"},"transactionDate":{"type":"string"},"transactionType":{"type":"string"},"sourceURL":{"type":"string"}}}}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

INSERT INTO catalog.capabilities(slug,name,description,category,input_contract,output_contract,status) VALUES('finance_markets.cityfalcon-investor-relations','Investor relations documents','CityFALCON investor relations documents for explicit full tickers (AAPL_US). Recent 30-day provider window only; this is the returned page, not an exhaustive historical record.  Use optional period/date fields when requested.','finance','{"type":"object","title":"Retrieves investor relations document links and metadata","$schema":"http://json-schema.org/draft-07/schema#","required":["identifiers"],"properties":{"type":{"type":"string","example":"Earnings,Press Release","description":"Comma-separated record types, e.g. \"Earnings, Others, Financial Statements, Press Release\"."},"end_date":{"type":"string","format":"date","example":"2023-03-18","description":"Date to retrieve data to. Format YYYY-MM-DD, e.g. \"2023-03-18\"."},"start_date":{"type":"string","format":"date","example":"2023-03-18","description":"Date to retrieve data from. Format YYYY-MM-DD, e.g. \"2023-03-18\". Limited to the most recent 30 days; older data is available as CSV from CityFALCON."},"identifiers":{"type":"string","example":"AAPL_US","description":"Comma-separated identifiers, format [ticker]_[trading_country], e.g. \"AAPL_US, 005930_KR\"."}},"description":"Query parameters for GET https://api.cityfalcon.com/v0.2/investor_relations. Auth: access_token."}'::jsonb,'{"type":"array","items":{"type":"object","required":["companyTicker","title","link"],"properties":{"companyTicker":{"type":"string"},"title":{"type":"string"},"link":{"type":"string"}}}}'::jsonb,'active') ON CONFLICT(slug) DO NOTHING;

